/**
 * `Icon`, the design system's way to place a lucide icon by name: `<Icon name="Trash2" size={16} />`.
 * It carries exactly the icons the app imports (`virtual:design-system-icons`, generated by
 * scripts/design-system/icons.mjs). Other props reach the icon's `<svg>`. An unknown name renders
 * nothing and says so in the console, once per name.
 */
import { useEffect, type Ref } from 'react';
import type { LucideProps } from 'lucide-react';
import { ICONS } from 'virtual:design-system-icons';

export type IconProps = Omit<LucideProps, 'ref'> & { name: string; ref?: Ref<SVGSVGElement> };

const warned = new Set<string>();

export function Icon({ name, size = 16, ...rest }: IconProps) {
  const Glyph = Object.hasOwn(ICONS, name) ? ICONS[name] : undefined;
  useEffect(() => {
    if (Glyph || warned.has(name)) return;
    warned.add(name);
    console.warn(`Icon: unknown icon "${name}"`);
  }, [Glyph, name]);
  return Glyph ? <Glyph size={size} {...rest} /> : null;
}
